  @override
  String get legalDisclaimerAINotLawyerBody =>
      'Bei den KI-Systemen von Umbrella handelt es sich um große Sprachmodelle, die auf allgemeinen Rechtskorpora trainiert werden. Sie sind nicht im Besitz einer Anwaltslizenz, können nicht vor Gericht erscheinen, unterliegen keiner Anwaltskammer oder Anwaltskammer und haben Ihnen gegenüber keine Fürsorgepflicht wie ein Anwalt. KI-Ausgaben können: sachliche Fehler oder Halluzinationen enthalten; Lassen Sie wesentliche Überlegungen aus, die für Ihre spezifischen Fakten relevant sind. zitieren Sie Gesetze oder Fälle, die geändert, aufgehoben oder außer Kraft gesetzt wurden; die jüngsten Gesetzesänderungen nicht berücksichtigen; und komplexe oder mehrdeutige Rechtsfragen falsch interpretieren. Sie müssen jede KI-Ausgabe als Ausgangspunkt für die Untersuchung betrachten, nicht als endgültige Antwort.';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. KI ist kein Anwalt';

  @override
  String get legalDisclaimerCitationBody =>
      'Wenn Umbrella ein Gesetz, eine Verordnung, eine Regel oder eine Gerichtsentscheidung zitiert, müssen Sie unabhängig überprüfen: (a) dass die zitierte Quelle existiert; (b) dass das Zitat korrekt ist (Abschnitt, Unterabschnitt und Jahr); (c) dass die Quelle derzeit in Kraft ist und nicht geändert oder aufgehoben wurde; (d) dass der zitierte Text die Quelle genau wiedergibt. KI-Zitierfehler – einschließlich erfundener Zitate – sind eine bekannte Einschränkung aller aktuellen KI-Systeme. Verlassen Sie sich in Gerichtsverfahren, Ratschlägen oder Einreichungen niemals auf ein Zitat ohne unabhängige Überprüfung.';

  @override
  String get legalDisclaimerCitationHeading => '4. Zitiergenauigkeit';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'Indien: Die KI-Analyse basiert auf zentraler Gesetzgebung, staatlichen Gesetzen, sofern angegeben, und veröffentlichten Gerichtsentscheidungen. Die Praxis auf Bezirksgerichtsebene, örtliche Anwaltsbräuche oder nicht kodifizierte Verfahrensregeln werden nicht berücksichtigt. Vereinigte Staaten: Die KI-Analyse basiert auf Bundesrecht und ausgewähltem Landesrecht. Eine US-amerikanische Rechtsanalyse ist kein Ersatz für einen staatsspezifischen, zugelassenen Rechtsbeistand. Für Einwanderungs-, Strafverteidigungs- oder Steuerangelegenheiten ohne verifizierte anwaltliche Überprüfung nicht verfügbar. Kenia: Die Analyse stützt sich auf kenianische Gesetze, Nebengesetze und veröffentlichte Entscheidungen des Obersten Gerichtshofs und des Berufungsgerichts. Es berücksichtigt nicht das Gewohnheitsrecht, Abweichungen von Amtsgerichten oder unveröffentlichte Urteile. Vereinigtes Königreich: Die Analyse umfasst englisches und walisisches Recht. Schottisches Recht, nordirisches Recht und dezentrale Angelegenheiten können sich erheblich unterscheiden; Holen Sie sich gerichtsspezifische Beratung ein.';

  @override
  String get legalDisclaimerJurisdictionHeading =>
      '8. Gerichtsstandsbeschränkungen';

  @override
  String get legalDisclaimerLawyerReviewBody =>
      'Bestimmte Umbrella-Ausgaben tragen das Abzeichen „Anwalt geprüft“, was darauf hinweist, dass ein zugelassener Anwalt auf unserem Marktplatz den Inhalt überprüft und genehmigt hat. Sogar überprüfte Ergebnisse: (a) spiegeln die Meinung des Anwalts zum Zeitpunkt der Überprüfung wider; (b) stellen kein formelles Rechtsgutachten dar, sofern nicht ein unterzeichnetes Gutachten beigefügt ist; (c) keine Beziehung zwischen Anwalt und Mandant begründen, es sei denn, es wird eine gesonderte Mandatsvereinbarung abgeschlossen; (d) können aufgrund von Gesetzesänderungen veraltet sein. Der prüfende Anwalt ist ein unabhängiger Auftragnehmer; DVTech Ventures übernimmt keine Garantie für die Qualität oder Genauigkeit der überprüften Ergebnisse.';

  @override
  String get legalDisclaimerLawyerReviewHeading =>
      '7. Von Anwälten überprüfte Ergebnisse';

  @override
  String get legalDisclaimerNoPrivilegeBody =>
      'Die Kommunikation mit der KI von Umbrella ist in keiner Gerichtsbarkeit durch das Anwaltsgeheimnis oder das Anwaltsgeheimnis geschützt. Übermitteln Sie der Plattform keine Informationen, die Sie privilegiert schützen möchten. Wenn Sie einen zugelassenen Anwalt über den Umbrella-Marktplatz beauftragen, können Privilegien an Ihre Kommunikation mit diesem Anwalt im Rahmen einer abgeschlossenen Mandatsvereinbarung geknüpft sein, nicht jedoch an Ihre vorherigen KI-Interaktionen.';

