      'DVTech Ventures ist ein Technologieunternehmen und kein regulierter Rechtsdienstleister. Wir sind nicht von der Solicitors Regulation Authority (UK), dem Bar Council of India, der Law Society of Kenya, einer Anwaltskammer eines US-Bundesstaates oder einer anderen gesetzlichen Regulierungsbehörde zur Erbringung von Rechtsdienstleistungen autorisiert. Die Umbrella-Plattform bietet keine regulierte Rechtstätigkeit im Sinne des Legal Services Act 2007 (UK) oder gleichwertiger Gesetze in anderen Gerichtsbarkeiten an.';

