      'Dieser Haftungsausschluss gilt für alle Funktionen der Umbrella-Plattform, einschließlich, aber nicht beschränkt auf: den Legal Issue Checker, AI Copilot, Dokumentenprüfung, Rechtsrecherche, Sachverhaltsanalyse, Strategiememos, Dokumentenentwürfe und alle anderen KI-generierten Inhalte. Sie gilt für alle Benutzer – Verbraucher, Anwaltsbenutzer und Anwaltskanzleien – in allen Gerichtsbarkeiten, in denen Umbrella tätig ist (Indien, Vereinigte Staaten, Kenia und Vereinigtes Königreich).';

