  @override
  String get legalDisclaimerUniversalBody =>
      'Umbrella bietet rechtliche Informationen, Dokumenterklärungen, Problemerkennung und Risikoanalysen. Es handelt sich nicht um eine Anwaltskanzlei und ersetzt keinen zugelassenen Anwalt. Für eine auf Ihre Situation zugeschnittene Rechtsberatung wenden Sie sich bitte an einen qualifizierten Anwalt in Ihrem Zuständigkeitsbereich. KI-generierte Inhalte werden nur zu Informationszwecken bereitgestellt und stellen keine Rechtsberatung, Rechtsvertretung oder den Aufbau eines Anwalt-Mandanten-Verhältnisses zwischen Ihnen und DVTech Ventures dar.';

