  @override
  String get legalPrivacyAutomatedBody =>
      'Umbrella nutzt KI, um rechtliche Analysen zu erstellen, Probleme zu identifizieren und Maßnahmen vorzuschlagen. Diese KI-Ausgaben dienen nur der Information und stellen keine verbindliche Entscheidung über Ihre gesetzlichen Rechte dar. Ohne menschliche Prüfung wird über Sie keine vollautomatisierte Entscheidung mit rechtlicher oder ähnlich bedeutsamer Wirkung getroffen. Unsere KI-Risikobewertung zur Betrugserkennung kann sich auf den Plattformzugriff auswirken; Sie können eine menschliche Überprüfung einer solchen Entscheidung beantragen.';

