  @override
  String get legalPrivacyCollectContentBody =>
      'Inhaltsdaten: Rechtsdokumente, Fallbeschreibungen, Sachverhaltsnotizen, Kundenkommunikation und KI-generierte Ausgaben, die Sie erstellen oder über die Plattform einreichen. Diese Inhalte werden zur Bereitstellung des Dienstes verarbeitet und ohne Ihr ausdrückliches Einverständnis nicht für KI-Schulungen verwendet.';

  @override
  String get legalPrivacyCollectCookiesBody =>
      'Cookies und Tracking: Wir verwenden unbedingt notwendige Sitzungscookies, funktionale Präferenzcookies und – mit Ihrer Zustimmung – Analysecookies (Vercel Analytics, Sentry-Fehlerverfolgung). Sie können die Cookie-Einstellungen über das Cookie-Einstellungsfeld verwalten.';

