  @override
  String get legalPrivacyCollectUsageBody =>
      'Nutzungsdaten: besuchte Seiten, genutzte Funktionen, übermittelte KI-Anfragen, hochgeladene Dokumente, aufgewendete Zeit, Klickereignisse und Sitzungsaufzeichnungen (sofern eine Einwilligung vorliegt). Diese Daten werden über First-Party-Analysen erfasst.';

  @override
  String get legalPrivacyContactBody =>
      'Datenschutzanfragen: support@odaflow.com. Unser Ziel ist es, innerhalb von 10 Werktagen zu antworten. Wenn Sie mit unserer Antwort nicht zufrieden sind, haben Sie das Recht, eine Beschwerde bei Ihrer örtlichen Datenschutzbehörde einzureichen: UK – ICO (ico.org.uk); EU – Ihre nationale Datenschutzbehörde; Indien – Datenschutzbehörde von Indien; Kenia – Büro des Datenschutzbeauftragten (odpc.go.ke).';

  @override
  String get legalPrivacyContactHeading => '14. Kontaktieren Sie uns';

  @override
  String get legalPrivacyControllerBody =>
      'Umbrella wird von DVTech Ventures („wir“, „uns“, „unser“) betrieben. Wir fungieren als Datenverantwortlicher für die von Verbrauchern erfassten Daten und als Datenverarbeiter für Daten, die im Namen der Mieter von Anwaltskanzleien gespeichert werden. Registrierte Adresse und Datenschutzkontakt: support@odaflow.com. Für DSGVO-Zwecke kann unser EU-/UK-Vertreter unter derselben Adresse kontaktiert werden.';

  @override
  String get legalPrivacyControllerHeading => '1. Wer wir sind';

  @override
  String get legalPrivacyCookiesBody =>
      'Unbedingt notwendige Cookies (Sitzungsverwaltung, Sicherheitstoken) sind immer aktiv. Funktionale Cookies (Spracheinstellung, Thema) werden bei der ersten Verwendung gesetzt und können in den Browsereinstellungen gelöscht werden. Analytics-Cookies (Vercel, Sentry) werden nur mit Ihrer Zustimmung über das Cookie-Banner gesetzt. Wir verwenden keine Werbe- oder Cross-Site-Tracking-Cookies.';

  @override
  String get legalPrivacyCookiesHeading => '12. Cookies';

  @override
  String get legalPrivacyDescription =>
      'Wie Umbrella Ihre Daten erhebt, nutzt und schützt. Diese Richtlinie gilt für alle Benutzer von Umbrella.okaylegal.ai und zugehörigen Umbrella-Anwendungen in Indien, den Vereinigten Staaten, Kenia und dem Vereinigten Königreich.';

  @override
  String get legalPrivacyLegalBasisBody =>
      'Wir verarbeiten personenbezogene Daten auf der Grundlage der folgenden Rechtsgrundlagen, abhängig von Ihrer Gerichtsbarkeit: (a) Vertrag – Verarbeitung, die für die Erbringung von Dienstleistungen erforderlich ist, für die Sie sich angemeldet haben; (b) Berechtigte Interessen – Betrugsprävention, Plattformsicherheit, Produktverbesserung; (c) Einwilligung – KI-Schulung, Marketing-E-Mails, Cookies, die über das unbedingt Notwendige hinausgehen; (d) Gesetzliche Verpflichtung – Einhaltung des geltenden Rechts. Für Indien unterliegt die Verarbeitung dem Digital Personal Data Protection Act 2023 (DPDP Act). Für das Vereinigte Königreich/die EU erfolgt die Verarbeitung im Einklang mit der UK-DSGVO und der EU-DSGVO. Für Kenia erfolgt die Verarbeitung im Einklang mit dem Data Protection Act 2019. Für US-Benutzer halten wir uns an die geltenden Datenschutzgesetze der Bundesstaaten, einschließlich CCPA/CPRA.';

  @override
  String get legalPrivacyLegalBasisHeading =>
      '2. Rechtsgrundlagen der Verarbeitung';

  @override
  String get legalPrivacyPolicy => 'Datenschutzrichtlinie';

  @override
  String get legalPrivacyRetentionBody =>
      'Wir speichern personenbezogene Daten so lange, wie Ihr Konto aktiv ist. Bei der Löschung eines Kontos löschen oder anonymisieren wir personenbezogene Daten innerhalb von 30 Tagen, es sei denn, die Aufbewahrung ist gesetzlich vorgeschrieben (z. B. werden Abrechnungsunterlagen aus Gründen der Steuerkonformität 7 Jahre lang aufbewahrt, Prüfprotokolle werden 12 Monate lang aufbewahrt). Firmenmandanten können über Governance-Einstellungen benutzerdefinierte Aufbewahrungsrichtlinien für bis zu 7 Jahre konfigurieren. KI-Trainingsdatensätze, die aus aktivierten Inhalten abgeleitet werden, unterliegen dem Aufbewahrungsplan in unserer Daten- und KI-Einwilligungsrichtlinie.';

  @override
