  @override
  String get legalPrivacySecurityBody =>
      'Wir implementieren technische und organisatorische Maßnahmen, darunter: TLS 1.2+-Verschlüsselung bei der Übertragung; AES-256-Verschlüsselung im Ruhezustand; rollenbasierte Zugriffskontrolle mit dem Prinzip der geringsten Rechte; Multi-Faktor-Authentifizierung für administrativen Zugriff; automatisiertes Scannen von Schwachstellen; Penetrationstests mindestens einmal jährlich; und einen Plan zur Reaktion auf Vorfälle. Im Falle einer Verletzung des Schutzes personenbezogener Daten, die Ihre Rechte beeinträchtigt, werden wir Sie innerhalb von 72 Stunden nach Kenntniserlangung benachrichtigen, wie nach geltendem Recht erforderlich.';

