  @override
  String get legalTermsDefinitionsBody =>
      '„Plattform“ bezeichnet Umbrella.okaylegal.ai und alle zugehörigen Anwendungen, APIs und Dienste. „Verbrauchernutzer“ ist eine natürliche Person, die die Plattform nutzt, um sich über ihre eigene Rechtslage zu informieren. „Anwaltsbenutzer“ bezeichnet einen lizenzierten Anwalt, der die Funktionen des Lawyer OS nutzt. „Mieter“ bezeichnet eine Anwaltskanzlei oder Organisation mit einem Firmenabonnement. „KI-Ausgabe“ bezeichnet alle Texte, Analysen, Entwürfe oder Empfehlungen, die von den KI-Systemen von Umbrella generiert werden. „Angelegenheit“ bezeichnet einen Rechtsfall oder eine Transaktion, die über das Lawyer OS verwaltet wird. „DVTech Ventures“ oder „wir“ bezeichnet den Betreiber der Plattform.';

